import type { Menu as ShardsMenu } from "@shardsui/svelte";
import type { ComponentProps, Snippet } from "svelte";
import type { HTMLButtonAttributes, SvelteHTMLElements } from "svelte/elements";

type PartProps<Args extends unknown[] = []> = Omit<SvelteHTMLElements["div"], "children" | "id"> & {
  as?: keyof HTMLElementTagNameMap;
  children?: Snippet<Args>;
  id?: string;
  ref?: HTMLElement | null;
};

export type MenuTriggerState = {
  disabled: boolean;
  open: boolean;
};

export type MenuCheckableItemState = {
  checked: boolean;
  disabled: boolean;
  highlighted: boolean;
};

export type MenuRootState<Payload> = {
  payload: Payload | undefined;
};

export type MenuRootProps<Payload = unknown> = {
  children?: Snippet<[MenuRootState<Payload>]>;
  closeParentOnEsc?: boolean;
  defaultOpen?: boolean;
  disabled?: boolean;
  handle?: ShardsMenu.Handle<Payload>;
  highlightItemOnHover?: boolean;
  loopFocus?: boolean;
  modal?: boolean;
  onOpenChange?: (open: boolean) => void;
  onOpenChangeComplete?: (open: boolean) => void;
  open?: boolean;
  orientation?: "horizontal" | "vertical";
  triggerId?: string | null;
};

export type MenuTriggerProps<Payload = unknown> = Omit<HTMLButtonAttributes, "children" | "id"> & {
  as?: keyof HTMLElementTagNameMap;
  children?: Snippet<[MenuTriggerState]>;
  closeDelay?: number;
  delay?: number;
  disabled?: boolean;
  handle?: ShardsMenu.Handle<Payload>;
  id?: string;
  openOnHover?: boolean;
  payload?: Payload;
  ref?: HTMLElement | null;
};

type PrimitivePopupProps = ComponentProps<typeof ShardsMenu.Popup>;
type PositionerProps = ComponentProps<typeof ShardsMenu.Positioner>;

export type MenuPopupProps = PrimitivePopupProps & {
  align?: PositionerProps["align"];
  alignOffset?: PositionerProps["alignOffset"];
  anchor?: PositionerProps["anchor"];
  portalProps?: ComponentProps<typeof ShardsMenu.Portal>;
  side?: PositionerProps["side"];
  sideOffset?: PositionerProps["sideOffset"];
};

export type MenuCheckboxItemProps = Omit<
  ComponentProps<typeof ShardsMenu.CheckboxItem>,
  "checked"
> & {
  checked?: boolean;
  defaultChecked?: boolean;
  variant?: "default" | "switch";
};

export type MenuGroupProps = ComponentProps<typeof ShardsMenu.Group>;
export type MenuGroupLabelProps = ComponentProps<typeof ShardsMenu.GroupLabel> & {
  inset?: boolean;
};
export type MenuItemProps = ComponentProps<typeof ShardsMenu.Item> & {
  inset?: boolean;
  variant?: "default" | "destructive";
};
export type MenuLinkItemProps = ComponentProps<typeof ShardsMenu.LinkItem> & {
  inset?: boolean;
  variant?: "default" | "destructive";
};
export type MenuRadioGroupProps<Value = unknown> = Omit<
  ComponentProps<typeof ShardsMenu.RadioGroup>,
  "onValueChange" | "value"
> & {
  defaultValue?: Value;
  onValueChange?: (value: Value) => void;
  value?: Value;
};
export type MenuRadioItemProps = PartProps<[MenuCheckableItemState]> & {
  closeOnClick?: boolean;
  disabled?: boolean;
  value: unknown;
};
export type MenuSeparatorProps = Omit<PartProps, "children">;
export type MenuShortcutProps = SvelteHTMLElements["kbd"] & {
  children?: Snippet;
  ref?: HTMLElement | null;
};
export type MenuSubProps = Omit<ComponentProps<typeof ShardsMenu.SubmenuRoot>, "open"> & {
  defaultOpen?: boolean;
  open?: boolean;
};
export type MenuSubTriggerProps = ComponentProps<typeof ShardsMenu.SubmenuTrigger> & {
  inset?: boolean;
};
export type MenuSubPopupProps = Omit<MenuPopupProps, "anchor" | "portalProps" | "side">;

import { Menu as MenuPrimitive } from "@shardsui/svelte";

export { MenuPrimitive };
export const Handle = MenuPrimitive.Handle;
export function createHandle<Payload = unknown>() {
  return new MenuPrimitive.Handle<Payload>();
}
export const MenuCreateHandle = createHandle;
export const DropdownMenuCreateHandle = createHandle;

export type {
  MenuCheckboxItemProps,
  MenuCheckableItemState,
  MenuGroupLabelProps,
  MenuGroupProps,
  MenuItemProps,
  MenuLinkItemProps,
  MenuPopupProps,
  MenuRadioGroupProps,
  MenuRadioItemProps,
  MenuRootProps,
  MenuRootState,
  MenuSeparatorProps,
  MenuShortcutProps,
  MenuSubPopupProps,
  MenuSubProps,
  MenuSubTriggerProps,
  MenuTriggerProps,
  MenuTriggerState,
} from "./menu.types.js";
export {
  default as CheckboxItem,
  default as DropdownMenuCheckboxItem,
  default as MenuCheckboxItem,
} from "./menu-checkbox-item.svelte";
export {
  default as DropdownMenuGroup,
  default as Group,
  default as MenuGroup,
} from "./menu-group.svelte";
export {
  default as DropdownMenuLabel,
  default as GroupLabel,
  default as Label,
  default as MenuGroupLabel,
} from "./menu-group-label.svelte";
export {
  default as DropdownMenuItem,
  default as Item,
  default as MenuItem,
} from "./menu-item.svelte";
export { default as LinkItem, default as MenuLinkItem } from "./menu-link-item.svelte";
export {
  default as Content,
  default as DropdownMenuContent,
  default as MenuPopup,
  default as Popup,
} from "./menu-popup.svelte";
export {
  default as DropdownMenuRadioGroup,
  default as MenuRadioGroup,
  default as RadioGroup,
} from "./menu-radio-group.svelte";
export {
  default as DropdownMenuRadioItem,
  default as MenuRadioItem,
  default as RadioItem,
} from "./menu-radio-item.svelte";
export {
  default as DropdownMenu,
  default as Menu,
  default as MenuRoot,
  default as Root,
} from "./menu-root.svelte";
export {
  default as DropdownMenuSeparator,
  default as MenuSeparator,
  default as Separator,
} from "./menu-separator.svelte";
export {
  default as DropdownMenuShortcut,
  default as MenuShortcut,
  default as Shortcut,
} from "./menu-shortcut.svelte";
export {
  default as DropdownMenuSub,
  default as MenuSub,
  default as Sub,
  default as SubmenuRoot,
} from "./menu-sub.svelte";
export {
  default as DropdownMenuSubContent,
  default as MenuSubPopup,
  default as SubContent,
  default as SubPopup,
} from "./menu-sub-popup.svelte";
export {
  default as DropdownMenuSubTrigger,
  default as MenuSubTrigger,
  default as SubTrigger,
  default as SubmenuTrigger,
} from "./menu-sub-trigger.svelte";
export {
  default as DropdownMenuTrigger,
  default as MenuTrigger,
  default as Trigger,
} from "./menu-trigger.svelte";

export const Portal: typeof MenuPrimitive.Portal = MenuPrimitive.Portal;
export const MenuPortal: typeof MenuPrimitive.Portal = MenuPrimitive.Portal;
export const DropdownMenuPortal: typeof MenuPrimitive.Portal = MenuPrimitive.Portal;
export const Positioner: typeof MenuPrimitive.Positioner = MenuPrimitive.Positioner;
export const Backdrop: typeof MenuPrimitive.Backdrop = MenuPrimitive.Backdrop;
export const Arrow: typeof MenuPrimitive.Arrow = MenuPrimitive.Arrow;
export const Viewport: typeof MenuPrimitive.Viewport = MenuPrimitive.Viewport;
